private static ComputedSpelExpression obtainComputedSpelExpression(
            final IEngineConfiguration configuration,
            final IStandardVariableExpression expression, final String spelExpression,
            final StandardExpressionExecutionContext expContext) {

        if (expContext.getRestrictExternalAccess()
                && SpringStandardExpressionUtils.containsExternalAccess(spelExpression)) {
            throw new TemplateProcessingException(
                "Instantiation of new objects and access to static classes or parameters is forbidden in this context");
        }

        if (expression instanceof VariableExpression) {

            final VariableExpression vexpression = (VariableExpression) expression;

            Object cachedExpression = vexpression.getCachedExpression();
            if (cachedExpression != null && cachedExpression instanceof ComputedSpelExpression) {
                return (ComputedSpelExpression) cachedExpression;
            }
            cachedExpression = getExpression(configuration, spelExpression);
            if (cachedExpression != null) {
                vexpression.setCachedExpression(cachedExpression);
            }
            return (ComputedSpelExpression) cachedExpression;

        }

        if (expression instanceof SelectionVariableExpression) {

            final SelectionVariableExpression vexpression = (SelectionVariableExpression) expression;

            Object cachedExpression = vexpression.getCachedExpression();
            if (cachedExpression != null && cachedExpression instanceof ComputedSpelExpression) {
                return (ComputedSpelExpression) cachedExpression;
            }
            cachedExpression = getExpression(configuration, spelExpression);
            if (cachedExpression != null) {
                vexpression.setCachedExpression(cachedExpression);
            }
            return (ComputedSpelExpression) cachedExpression;

        }

        return getExpression(configuration, spelExpression);

    }

private static boolean isLocalVariableOverriding(final IExpressionContext context, final String expression) {

        if (!(context instanceof IEngineContext)) {
            // We don't even have support for local variables!
            return false;
        }

        // NOTE this IEngineContext interface is internal and should not be used in users' code
        final IEngineContext engineContext = (IEngineContext) context;

        final int dotPos = expression.indexOf('.');
        if (dotPos == -1) {
            return false;
        }
        // Once we extract the first part of the expression, we check whether it is a local variable...
        final String expressionFirstComponent = expression.substring(0, dotPos);
        return engineContext.isVariableLocal(expressionFirstComponent);

    }

private static void checkRestrictedVariables(final SpelNode node) {
        if (node instanceof VariableReference) {
            final String name = node.toStringAST();
            if (name != null && name.length() > 1 && name.charAt(0) == '#') {
                final String varName = name.substring(1);
                if (ThymeleafEvaluationContext.RESTRICTED_VARIABLE_NAMES.contains(varName)) {
                    throw new TemplateProcessingException(
                            "Access to variable '" + name + "' is forbidden in this context");
                }
            }
        }
        for (int i = 0; i < node.getChildCount(); i++) {
            checkRestrictedVariables(node.getChild(i));
        }
    }

public ThymeleafEvaluationContextWrapper(final EvaluationContext delegate) {

        super();

        Validate.notNull(delegate, "Evaluation context delegate cannot be null");

        this.delegate = delegate;

        if (this.delegate instanceof ThymeleafEvaluationContext) {

            this.propertyAccessors = null; // No need to initialize our own property accessors
            this.typeLocator = null;       // No need to initialize our own type locator
            this.methodResolvers = null;   // No need to initialize our own method resolvers

        } else {

            // We need to wrap any reflective method resolvers in order to forbid calling methods on any of the blocked classes
            this.propertyAccessors =
                    Stream.concat(
                            Stream.of(SPELContextPropertyAccessor.INSTANCE, MAP_ACCESSOR_INSTANCE),
                            this.delegate.getPropertyAccessors().stream()
                                    .map(pa -> (pa instanceof ReflectivePropertyAccessor) ?
                                            new ThymeleafEvaluationContextACLPropertyAccessor((ReflectivePropertyAccessor) pa) : pa))
                        .collect(Collectors.toList());

            // We need to establish a custom type locator in order to forbid access to certain dangerous classes in expressions
            this.typeLocator =
                    new ThymeleafEvaluationContextACLTypeLocator(this.delegate.getTypeLocator());

            // We need to wrap any reflective method resolvers in order to forbid calling methods on any of the blocked classes
            this.methodResolvers =
                    this.delegate.getMethodResolvers().stream()
                        .map(mr -> (mr instanceof ReflectiveMethodResolver) ?
                                new ThymeleafEvaluationContextACLMethodResolver((ReflectiveMethodResolver) mr) : mr)
                        .collect(Collectors.toList());

        }

        // Build the SimpleEvaluationContext used in restricted mode: an empty evaluation context. This is because
        // resolution of property accessors and ACL method resolvers will be delegated to the superclass to allow for
        // customization by devs, and at the same time providing no constructor resolution at all, no type
        // references (T(...)) and no bean references (@bean), all of which are already blocked by the
        // expression-level checks but will also be blocked here, at the evaluation-context level.
        this.restrictedModeContext = SimpleEvaluationContext.forPropertyAccessors().build();

    }

public static IThymeleafBindStatus getBindStatusFromParsedExpression(
            final IExpressionContext context,
            final boolean optional, final boolean useSelectionAsRoot, final String expression) {

        /*
         * This version of the getBindStatus method should only be called after parsing, and therefore the
         * passed expression must be a fragment of the already parsed expression. Note this is important because
         * this method performs no preprocessing on the expression!
         */

        // This method will return null if no binding is found and optional == true

        final IThymeleafRequestContext requestContext = SpringContextUtils.getRequestContext(context);
        if (requestContext == null) {
            return null;
        }

        final String completeExpression =
                FieldUtils.validateAndGetValueExpression(context, useSelectionAsRoot, expression);

        if (completeExpression == null) {
            return null;
        }


        if (!optional) {
            return requestContext.getBindStatus(completeExpression, false);
        }


        if (isBound(requestContext, completeExpression)) {
            // Creating an instance of BindStatus for an unbound object results in an (expensive) exception,
            // so we avoid it by checking first. Because the check is a simplification, we still handle the exception.
            try {
                return requestContext.getBindStatus(completeExpression, false);
            } catch (final NotReadablePropertyException ignored) {
                return null;
            }
        }

        return null;

    }

