private static boolean containsExpression(final String text) {
        final int textLen = text.length();
        char c;
        boolean expInit = false;
        boolean preInit = false;
        boolean lsubInit = false;
        for (int i = 0; i < textLen; i++) {
            c = text.charAt(i);
            if (!expInit) {
                if (c == '$' || c == '*' || c == '#' || c == '@' || c == '~') {
                    expInit = true;
                }
            } else {
                if (c == '{') {
                    return true;
                } else if (!Character.isWhitespace(c)) {
                    expInit = false;
                }
            }
            if (c == '_' && (i + 1) < textLen && text.charAt(i + 1) == '_') {
                if (!preInit) {
                    preInit = true;
                    i++;
                } else {
                    return true;
                }
            }
            if (c == '|') {
                if (!lsubInit) {
                    lsubInit = true;
                } else {
                    return true;
                }
            }
        }
        return false;
    }

public TemplateProcessingException(final String message) {
        this(message, null);
    }

/**
     * Removes all whitespaces and control chars at all positions, and
     * transforms to lower case.
     *
     * @param target the string to be packed
     * @return the packed string
     *
     * @since 3.0.12
     */
public static String pack(final String target) {
        if (target == null) {
            return null;
        }
        final int targetLen = target.length();
        StringBuilder strBuilder = null;
        char c;
        for (int i = 0; i < targetLen; i++) {
            c = target.charAt(i);
            if (Character.isWhitespace(c) || c <= ' ') {
                if (strBuilder == null) {
                    strBuilder = new StringBuilder();
                    strBuilder.append(target, 0, i);
                }
            } else {
                if (strBuilder != null) {
                    strBuilder.append(c);
                }
            }
        }
        return (strBuilder == null) ? target.toLowerCase() : strBuilder.toString().toLowerCase();
    }

