private static int findEndOfNumericVersion(final CharSequence sequence) {
        final int seqLen = sequence.length();
        char c;
        for (int i = 0; i < seqLen; i++) {
            c = sequence.charAt(i);
            if (c != '.' && !Character.isDigit(c)) {
                if (i > 1 && sequence.charAt(i - 1) == '.') {
                    return i - 1;
                }
                return i;
            }
        }
        return -1;
    }

